import collections
import re

def count_most_common_words(file_path, top_n=3):
    """Counts words in a file and returns the top_n most common words with their counts."""
    with open(file_path, 'r') as f:
        text = f.read().lower()

    # Using regex to find words (alphanumeric)
    words = re.findall(r'\w+', text)

    if not words:
        return []

    counter = collections.Counter(words)
    return counter.most_common(top_n)

if __name__ == "__main__":
    file_path = 'file_1'
    try:
        top_words = count_most_common_words(file_path)
        if top_words:
            print(f"Top 3 most common words in {file_path}:")
            for word, count in top_words:
                print(f"{word}: {count}")
        else:
            print("No words found in the file.")
    except FileNotFoundError:
        print(f"Error: {file_path} not found.")

def count_primes(limit):
    """Counts the number of prime numbers strictly less than the limit."""
    if limit <= 2:
        return 0

    sieve = [True] * limit
    sieve[0] = sieve[1] = False

    for p in range(2, int(limit**0.5) + 1):
        if sieve[p]:
            for i in range(p * p, limit, p):
                sieve[i] = False

    return sum(sieve)

if __name__ == "__main__":
    limit = 10000
    result = count_primes(limit)
    print(f"Number of primes below {limit}: {result}")

    # Assert a known value to verify
    # Primes below 10: 2, 3, 5, 7 (count = 4)
    assert count_primes(10) == 4
    # Primes below 20: 2, 3, 5, 7, 11, 13, 17, 19 (count = 8)
    assert count_primes(20) == 8
